import { toMigrations } from "./migrate.js";

// The SQL files are generated by drizzle-kit (`pnpm db:generate`) and bundled as raw strings.
const appFiles = import.meta.glob("./migrations/app/*.sql", {
  query: "?raw",
  import: "default",
  eager: true,
}) as Record<string, string>;
const workspaceFiles = import.meta.glob("./migrations/workspace/*.sql", {
  query: "?raw",
  import: "default",
  eager: true,
}) as Record<string, string>;

export const appMigrations = toMigrations(appFiles);
export const workspaceMigrations = toMigrations(workspaceFiles);
